using System.ComponentModel;
using System.Net.Http.Json;
using System.Text;
using System.Text.Json;
using Microsoft.Extensions.AI;

namespace ResearchAgent;

/// <summary>
/// Provides web search and note-taking tools for the research agent.
/// </summary>
public sealed class ResearchTools
{
    private readonly HttpClient _httpClient;
    private readonly List<NoteEntry> _notes = [];

    public ResearchTools(HttpClient httpClient)
    {
        _httpClient = httpClient;
    }

    /// <summary>
    /// Gets the collected tools as a list of <see cref="AITool"/> instances.
    /// </summary>
    public IList<AITool> AsTools() =>
    [
        AIFunctionFactory.Create(SearchWebAsync, name: "search_web", description: "Search the web for information on a topic. Returns a list of results with titles, URLs, and snippets."),
        AIFunctionFactory.Create(SaveNote, name: "save_note", description: "Save a research note with a title and content. Use this to record important findings."),
        AIFunctionFactory.Create(GetNotes, name: "get_notes", description: "Retrieve all saved research notes collected so far."),
    ];

    [Description("Search the web for information on a topic. Returns a list of results with titles, URLs, and snippets.")]
    public async Task<IReadOnlyList<SearchResult>> SearchWebAsync(
        [Description("The search query to look up on the web.")] string query,
        [Description("Maximum number of results to return (1-10).")] int maxResults = 5,
        CancellationToken cancellationToken = default)
    {
        maxResults = Math.Clamp(maxResults, 1, 10);

        // Use the Brave Search API if a key is configured; otherwise fall back to a simulated response.
        var apiKey = Environment.GetEnvironmentVariable("BRAVE_SEARCH_API_KEY");
        if (!string.IsNullOrWhiteSpace(apiKey))
        {
            return await SearchBraveAsync(query, maxResults, apiKey, cancellationToken);
        }

        return SimulateSearch(query, maxResults);
    }

    [Description("Save a research note with a title and content. Use this to record important findings.")]
    public string SaveNote(
        [Description("A short title for the note.")] string title,
        [Description("The detailed content of the note.")] string content)
    {
        var entry = new NoteEntry(title, content, DateTime.UtcNow);
        _notes.Add(entry);
        return $"Note saved: \"{title}\" (total notes: {_notes.Count})";
    }

    [Description("Retrieve all saved research notes collected so far.")]
    public IReadOnlyList<NoteEntry> GetNotes() =>
        _notes.AsReadOnly();

    private async Task<IReadOnlyList<SearchResult>> SearchBraveAsync(
        string query, int maxResults, string apiKey, CancellationToken cancellationToken)
    {
        using var request = new HttpRequestMessage(HttpMethod.Get,
            $"https://api.search.brave.com/res/v1/web/search?q={Uri.EscapeDataString(query)}&count={maxResults}");
        request.Headers.Add("Accept", "application/json");
        request.Headers.Add("X-Subscription-Token", apiKey);

        using var response = await _httpClient.SendAsync(request, cancellationToken);
        response.EnsureSuccessStatusCode();

        using var doc = await JsonDocument.ParseAsync(
            await response.Content.ReadAsStreamAsync(cancellationToken), cancellationToken: cancellationToken);

        var results = new List<SearchResult>();
        if (doc.RootElement.TryGetProperty("web", out var web) &&
            web.TryGetProperty("results", out var items))
        {
            foreach (var item in items.EnumerateArray())
            {
                results.Add(new SearchResult(
                    item.GetProperty("title").GetString() ?? "",
                    item.GetProperty("url").GetString() ?? "",
                    item.TryGetProperty("description", out var desc) ? desc.GetString() ?? "" : ""));

                if (results.Count >= maxResults) break;
            }
        }

        return results;
    }

    private static IReadOnlyList<SearchResult> SimulateSearch(string query, int maxResults)
    {
        // Provide plausible simulated results so the agent loop can be tested without an API key.
        var results = new List<SearchResult>
        {
            new($"Overview of {query} - Wikipedia",
                $"https://en.wikipedia.org/wiki/{Uri.EscapeDataString(query)}",
                $"A comprehensive overview of {query}, covering history, key concepts, and recent developments in the field."),
            new($"{query}: Latest Research and Trends",
                $"https://research.example.com/{Uri.EscapeDataString(query)}",
                $"Recent research highlights emerging trends in {query}, including new methodologies and breakthrough findings from 2025-2026."),
            new($"Understanding {query} - A Beginner's Guide",
                $"https://learn.example.com/guide/{Uri.EscapeDataString(query)}",
                $"This guide introduces the fundamental principles of {query}, with practical examples and recommended resources for further study."),
            new($"{query} in Practice: Industry Applications",
                $"https://industry.example.com/{Uri.EscapeDataString(query)}",
                $"Explore how {query} is applied across industries including healthcare, finance, and technology, with real-world case studies."),
            new($"The Future of {query}",
                $"https://future.example.com/{Uri.EscapeDataString(query)}",
                $"Expert predictions on how {query} will evolve over the next decade, examining challenges, opportunities, and ethical considerations."),
        };

        return results.Take(maxResults).ToList();
    }
}

public sealed record SearchResult(string Title, string Url, string Snippet);

public sealed record NoteEntry(string Title, string Content, DateTime SavedAtUtc);

