using Microsoft.Agents.AI;
using Microsoft.Extensions.AI;
using OpenAI;
using ResearchAgent;

// --- Configuration -----------------------------------------------------------
var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable to run the research agent.");

var modelId = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini-2024-07-18";

// --- Build the IChatClient via MEAI ------------------------------------------
IChatClient chatClient = new OpenAIClient(apiKey)
    .GetChatClient(modelId)
    .AsIChatClient();

// --- Set up tools ------------------------------------------------------------
using var httpClient = new HttpClient();
var tools = new ResearchTools(httpClient);

// --- Create the ChatClientAgent ----------------------------------------------
var agent = new ChatClientAgent(
    chatClient,
    name: "ResearchAgent",
    instructions: """
        You are a research agent. Your job is to thoroughly research a topic the user provides.

        Follow this workflow:
        1. Break the topic into 2-3 specific search queries.
        2. Use the search_web tool for each query.
        3. Review the results and save the most important findings using save_note.
        4. After gathering enough information, use get_notes to review your collected notes.
        5. Produce a final summary that synthesizes all your notes into a clear, well-structured report.

        Guidelines:
        - Always cite sources with their URLs.
        - Save at least 3 notes before writing the summary.
        - Be factual and concise.
        """,
    description: "An agent that researches topics by searching the web and taking notes.",
    tools: tools.AsTools());

// --- Chat options with guardrails --------------------------------------------
var chatOptions = new ChatOptions
{
    Temperature = 0f,
    MaxOutputTokens = 2048,
};

var runOptions = new ChatClientAgentRunOptions(chatOptions);

// --- Get the topic from the user ---------------------------------------------
Console.WriteLine("╔══════════════════════════════════════╗");
Console.WriteLine("║       🔍 Research Agent              ║");
Console.WriteLine("╚══════════════════════════════════════╝");
Console.WriteLine();

string topic;
if (args.Length > 0)
{
    topic = string.Join(' ', args);
}
else
{
    Console.Write("Enter a research topic: ");
    topic = Console.ReadLine()?.Trim() ?? "";
}

if (string.IsNullOrWhiteSpace(topic))
{
    Console.Error.WriteLine("No topic provided. Exiting.");
    return 1;
}

Console.WriteLine();
Console.WriteLine($"Researching: {topic}");
Console.WriteLine(new string('─', 60));

// --- Run the agent with streaming output -------------------------------------
var messages = new List<ChatMessage>
{
    new(ChatRole.User, $"Research the following topic and provide a comprehensive summary: {topic}"),
};

using var cts = new CancellationTokenSource(TimeSpan.FromMinutes(3));

await foreach (var update in agent.RunStreamingAsync(
    messages, runOptions: runOptions, cancellationToken: cts.Token))
{
    Console.Write(update.Text);
}

Console.WriteLine();
Console.WriteLine(new string('─', 60));
Console.WriteLine("Research complete.");
return 0;

